import{_ as a,a as t,b as i}from"./chunks/gimbal_control_x500gz.EUWzYn2j.js";import{_ as o}from"./chunks/x500_gimbal.D1yxzs5f.js";import{_ as n}from"./chunks/typhoon.Bk7vnt6u.js";import{_ as s,c as l,o as r,al as h}from"./chunks/framework.CT7RwC5a.js";const y=JSON.parse('{"title":"Gimbal Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"en/advanced/gimbal_control.md","filePath":"en/advanced/gimbal_control.md"}'),c={name:"en/advanced/gimbal_control.md"};function m(d,e,p,g,u,b){return r(),l("div",null,e[0]||(e[0]=[h('<h1 id="gimbal-configuration" tabindex="-1">Gimbal Configuration <a class="header-anchor" href="#gimbal-configuration" aria-label="Permalink to &quot;Gimbal Configuration&quot;">​</a></h1><p>This page explains how to configure and control a gimbal that has an attached camera (or any other payload).</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>PX4 contains a generic mount/gimbal control driver that supports different input and output methods:</p><ul><li>The input method defines the protocol used to command a gimbal mount that is managed by PX4. This might be an RC controller, a MAVLink command sent by a GCS, or both — automatically switching between them.</li><li>The output method defines how PX4 communicates with the connected gimbal. The recommended protocol is MAVLink v2, but you can also connect directly to a flight controller PWM output port.</li></ul><p>PX4 takes the input signal and routes/translates it to be sent through to the output. Any input method can be selected to drive any output.</p><p>Both the input and output are configured using parameters. The input is set using the parameter <a href="./../advanced_config/parameter_reference.html#MNT_MODE_IN">MNT_MODE_IN</a>. By default this is set to <code>Disabled (-1)</code> and the driver does not run. After selecting the input mode, reboot the vehicle to start the mount driver.</p><p>You should set <code>MNT_MODE_IN</code> to one of: <code>RC (1)</code>, <code>MAVlink gimbal protocol v2 (4)</code> or <code>Auto (0)</code> (the other options are deprecated). If you select <code>Auto (0)</code>, the gimbal will automatically select either RC or or MAVLink input based on the latest input. Note that the auto-switch from MAVLink to RC requires a large stick motion!</p><p>The output is set using the <a href="./../advanced_config/parameter_reference.html#MNT_MODE_OUT">MNT_MODE_OUT</a> parameter. By default the output is set to a PXM port (<code>AUX (0)</code>). If the <a href="https://mavlink.io/en/services/gimbal_v2.html" target="_blank" rel="noreferrer">MAVLink Gimbal Protocol v2</a> is supported by your gimbal, you should instead select <code>MAVLink gimbal protocol v2 (2)</code>.</p><p>The full list of parameters for setting up the mount driver can be found in <a href="./../advanced_config/parameter_reference.html#mount">Parameter Reference &gt; Mount</a>. The relevant settings for a number of common gimbal configurations are described below.</p><h2 id="mavlink-gimbal-mnt-mode-out-mavlink" tabindex="-1">MAVLink Gimbal (MNT_MODE_OUT=MAVLINK) <a class="header-anchor" href="#mavlink-gimbal-mnt-mode-out-mavlink" aria-label="Permalink to &quot;MAVLink Gimbal (MNT_MODE_OUT=MAVLINK)&quot;">​</a></h2><p>Each physical gimbal device on the system must have its own high level gimbal manager, which is discoverable by a ground station using the MAVLink gimbal protocol. The ground station sends high level <a href="https://mavlink.io/en/services/gimbal_v2.html#gimbal-manager-messages" target="_blank" rel="noreferrer">MAVLink Gimbal Manager</a> commands to the manager of the gimbal it wants to control, and the manager will in turn send appropriate lower level &quot;gimbal device&quot; commands to control the gimbal.</p><p>PX4 can be configured as the gimbal manager to control a single gimbal device (which can either be physically connected or be a MAVLink gimbal that implements the <a href="https://mavlink.io/en/services/gimbal_v2.html#gimbal-device-messages" target="_blank" rel="noreferrer">gimbal device interface</a>).</p><p>To enable a MAVLink gimbal, first set parameter <a href="./../advanced_config/parameter_reference.html#MNT_MODE_IN">MNT_MODE_IN</a> to <code>MAVlink gimbal protocol v2</code> and <a href="./../advanced_config/parameter_reference.html#MNT_MODE_OUT">MNT_MODE_OUT</a> to <code>MAVLink gimbal protocol v2</code>.</p><p>The gimbal can be connected to <em>any free serial port</em> using the instructions in <a href="./../peripherals/mavlink_peripherals.html">MAVLink Peripherals (GCS/OSD/Companion)</a> (also see <a href="./../peripherals/serial_configuration.html#serial-port-configuration">Serial Port Configuration</a>). For example, if the <code>TELEM2</code> port on the flight controller is unused you can connect it to the gimbal and set the following PX4 parameters:</p><ul><li><a href="./../advanced_config/parameter_reference.html#MAV_1_CONFIG">MAV_1_CONFIG</a> to <strong>TELEM2</strong> (if <code>MAV_1_CONFIG</code> is already used for a companion computer (say), use <code>MAV_2_CONFIG</code>).</li><li><a href="./../advanced_config/parameter_reference.html#MAV_1_MODE">MAV_1_MODE</a> to <strong>Gimbal</strong></li><li><a href="./../advanced_config/parameter_reference.html#MAV_1_FLOW_CTRL">MAV_1_FLOW_CTRL</a> to <strong>Off (0)</strong> (very few gimbals will have RST/CST wires connected).</li><li><a href="./../advanced_config/parameter_reference.html#MAV_1_FORWARD">MAV_1_FORWARD</a> to <strong>Enabled</strong> (Note strictly necessary as forwarding is enabled when <code>MAV_1_MODE</code> is set to Gimbal).</li><li><a href="./../advanced_config/parameter_reference.html#SER_TEL2_BAUD">SER_TEL2_BAUD</a> to manufacturer recommended baud rate.</li></ul><h3 id="multiple-gimbal-support" tabindex="-1">Multiple Gimbal Support <a class="header-anchor" href="#multiple-gimbal-support" aria-label="Permalink to &quot;Multiple Gimbal Support&quot;">​</a></h3><p>PX4 can automatically create a gimbal manager for a connected PWM gimbal or the first MAVLink gimbal device with the same system id it detects on any interface. It does not automatically create gimbal manager for any other MAVLink gimbal devices that it detects.</p><p>You can support additional MAVLink gimbals provided that they:</p><ul><li>Implement the gimbal <em>manager</em> protocol.</li><li>Are visible to the ground station and PX4 on the MAVLink network. This may require that traffic forwarding be configured between PX4, the GCS, and the gimbal.</li><li>Have a unique component id, and this component id must be in the range 7 - 255.</li></ul><h2 id="gimbal-on-fc-pwm-output-mnt-mode-out-aux" tabindex="-1">Gimbal on FC PWM Output (MNT_MODE_OUT=AUX) <a class="header-anchor" href="#gimbal-on-fc-pwm-output-mnt-mode-out-aux" aria-label="Permalink to &quot;Gimbal on FC PWM Output (MNT_MODE_OUT=AUX)&quot;">​</a></h2><p>The gimbal can also be controlled by connecting it to up to three flight controller PWM ports and setting the output mode to <code>MNT_MODE_OUT=AUX</code>.</p><p>The output pins that are used to control the gimbal are set in the <a href="./../config/actuators.html#actuator-outputs">Acuator Configuration &gt; Outputs</a> by selecting any three unused Actuator Outputs and assigning them the following output functions:</p><ul><li><code>Gimbal Roll</code>: Output controls gimbal roll.</li><li><code>Gimbal Pitch</code>: Output controls Gimbal pitch.</li><li><code>Gimbal Yaw</code>: Output controls Gimbal yaw.</li></ul><p>For example, you might have the following settings to assign the gimbal roll, pitch and yaw to AUX1-3 outputs.</p><p><img src="'+a+'" alt="Gimbal Actuator config"></p><p>The PWM values to use for the disarmed, maximum and minimum values can be determined in the same way as other servo, using the <a href="./../config/actuators.html#actuator-testing">Actuator Test sliders</a> to confirm that each slider moves the appropriate axis, and changing the values so that the gimbal is in the appropriate position at the disarmed, low and high position in the slider. The values may also be provided in gimbal documentation.</p><h2 id="gimbal-control-in-missions" tabindex="-1">Gimbal Control in Missions <a class="header-anchor" href="#gimbal-control-in-missions" aria-label="Permalink to &quot;Gimbal Control in Missions&quot;">​</a></h2><p><a href="https://mavlink.io/en/services/gimbal_v2.html#gimbal-manager-messages" target="_blank" rel="noreferrer">Gimbal Manager commands</a> may be used in missions if supported by the vehicle type. For example <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_GIMBAL_MANAGER_PITCHYAW" target="_blank" rel="noreferrer">MAV_CMD_DO_GIMBAL_MANAGER_PITCHYAW</a> is supported in <a href="./../flight_modes_mc/mission.html">multicopter mission mode</a>.</p><p>In theory you can address commands to a particular gimbal, specifying its component id using the &quot;Gimbal device id&quot; parameter. However at time of writing (December 2024) this is <a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/modules/gimbal/input_mavlink.cpp#L889" target="_blank" rel="noreferrer">not supported</a>: all mission commands are sent to the (only) gimbal managed by the PX4 gimbal manager (if this is a MAVLink gimbal, it will be the gimbal with component id defined in the parameter <a href="./../advanced_config/parameter_reference.html#MNT_MAV_COMPID">MNT_MAV_COMPID</a>, which is set by default to <a href="https://mavlink.io/en/messages/common.html#MAV_COMP_ID_GIMBAL" target="_blank" rel="noreferrer">MAV_COMP_ID_GIMBAL (154)</a>).</p><p>Gimbal movement is not immediate. To ensure that the gimbal has time to move into position before the mission progresses to the next item (if gimbal feedback is not provided or lost), you should set <a href="./../advanced_config/parameter_reference.html#MIS_COMMAND_TOUT">MIS_COMMAND_TOUT</a> to be greater than the time taken for the gimbal to traverse its full range. After this timeout the mission will proceed to the next item.</p><h2 id="simulation-sitl" tabindex="-1">Simulation / SITL <a class="header-anchor" href="#simulation-sitl" aria-label="Permalink to &quot;Simulation / SITL&quot;">​</a></h2><p>The following simulation environments come with a preconfigured simulated gimbal. You can test the gimbal using the <a href="#qgc-testing">QGroundControl UI</a> or by sending <a href="#driver-testing">driver commands</a></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you only need to test the <a href="./../modules/modules_driver.html#gimbal">gimbal driver</a>, then you can do this on any model or simulators. Just make sure that the driver runs, using <code>gimbal start</code> in the MAVLink console, then configure the driver parameters.</p></div><h3 id="gazebo" tabindex="-1">Gazebo <a class="header-anchor" href="#gazebo" aria-label="Permalink to &quot;Gazebo&quot;">​</a></h3><p>To run the <a href="./../sim_gazebo_gz/">Gazebo</a> simulation <a href="./../sim_gazebo_gz/vehicles.html#x500-quadrotor-with-gimbal-front-facing">Quadrotor(x500) with gimbal (Front-facing) in Gazebo</a>, use:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gz_x500_gimbal</span></span></code></pre></div><p><img src="'+o+'" alt="Quadrotor(x500) with gimbal (Front-facing) in Gazebo"></p><h3 id="gazebo-classic" tabindex="-1">Gazebo Classic <a class="header-anchor" href="#gazebo-classic" aria-label="Permalink to &quot;Gazebo Classic&quot;">​</a></h3><p>To run the <a href="./../sim_gazebo_classic/">Gazebo Classic</a> simulation <a href="./../sim_gazebo_classic/vehicles.html#typhoon-h480-hexrotor">Typhoon H480 model</a>, use:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gazebo-classic_typhoon_h480</span></span></code></pre></div><p><img src="'+n+'" alt="Typhoon H480 in Gazebo Classic"></p><p><img src="'+t+'" alt="Gazebo Gimbal Simulation"></p><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><h3 id="qgc-testing" tabindex="-1">QGC Testing <a class="header-anchor" href="#qgc-testing" aria-label="Permalink to &quot;QGC Testing&quot;">​</a></h3><p>The on-screen gimbal control can be used to move/test a connected MAVLink camera:</p><ol><li><p>Start your preferred <a href="#simulation-sitl">simulator</a> or connect to a real device.</p></li><li><p>Open QGroundControl and enable the on-screen camera control (Application settings).</p><p><img src="'+i+'" alt="Quadrotor(x500) with gimbal (Front-facing) in Gazebo"></p></li><li><p>Make sure the vehicle is armed and flying, e.g. by entering with <code>commander takeoff</code>.</p></li><li><p>To change gimbal target position, click in the QGC GUI up, down, left, right, or use the buttons on the gimbal control (<strong>Center</strong>, <strong>Tilt 90</strong>, <strong>Yaw lock</strong>).</p></li></ol><h3 id="driver-testing" tabindex="-1">Driver Testing <a class="header-anchor" href="#driver-testing" aria-label="Permalink to &quot;Driver Testing&quot;">​</a></h3><p>You can test a gimbal by sending <code>gimbal</code> driver commands in the <a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/analyze_view/mavlink_console.html" target="_blank" rel="noreferrer">QGroundControl MAVLink Console</a>:</p><ol><li>Start your preferred <a href="#simulation-sitl">simulator</a> or connect to a real device.</li><li>Open QGroundControl and connect to your vehicle.</li><li>Open the MAVLink Console using the menu: <strong>Analyze &gt; Mavlink Console</strong>.</li><li>Make sure the vehicle is armed and flying, e.g. by entering the command: <code>commander takeoff</code>.</li></ol><p>To check gimbal status enter:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gimbal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>To set the gimbal yaw to 30 degrees, use the command:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gimbal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yaw</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 30</span></span></code></pre></div><p>More generally, you can set the angle or angular rate command using a command with this format:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gimbal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">axi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">valu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><ul><li><code>axis</code>: <ul><li><code>&lt;roll|pitch|yaw&gt;</code> for angles</li><li><code>&lt;rollrate|pitchrate|yawrate&gt;</code> for angular rates</li></ul></li><li><code>value</code>: <ul><li><code>&lt;degrees&gt;</code> for angles</li><li><code>&lt;degrees / second&gt;</code> for angular rates</li></ul></li></ul><p>To set the MAVLink component that is in primary control of the gimbal:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gimbal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> primary-control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sys_i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">comp_i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><ul><li><code>sys_id</code>: MAVLink system ID</li><li><code>comp_id</code>: MAVLink component ID</li></ul><p>For other commands, see the <a href="./../modules/modules_driver.html#gimbal"><code>gimbal</code></a> driver module document.</p><h3 id="mavlink-testing" tabindex="-1">MAVLink Testing <a class="header-anchor" href="#mavlink-testing" aria-label="Permalink to &quot;MAVLink Testing&quot;">​</a></h3><p>The gimbal can be tested by sending MAVLink gimbal manager commands using <a href="./../robotics/mavsdk.html">MAVSDK</a> or some other MAVLink library.</p><p>Note that the simulated gimbal stabilizes itself, so if you send MAVLink commands, set the <code>stabilize</code> flags to <code>false</code>.</p>',64)]))}const M=s(c,[["render",m]]);export{y as __pageData,M as default};
